"""Seven static reference projects. Deliberately no application backend."""
from pathlib import Path
from html import escape
import zipfile,json
PUBLICATION=json.loads((Path(__file__).resolve().parents[1]/'content/publication.json').read_text())
CSS='''*{box-sizing:border-box}body{font:18px/1.75 system-ui,sans-serif;color:#24392d;background:#faf8f1;margin:0}header,main,footer{max-width:960px;margin:auto;padding:25px}header{border-bottom:1px solid #cad1c4}nav{display:flex;flex-wrap:wrap;gap:22px}a{color:#215243;text-underline-offset:4px}a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #a74125;outline-offset:3px}h1{font:52px/1.15 Georgia,serif}h2{font:30px/1.3 Georgia,serif}section{margin:35px 0}.note{padding:16px 20px;border-left:3px solid #a74125;background:#efeee4}table{width:100%;border-collapse:collapse}td,th{padding:13px;text-align:left;border-bottom:1px solid #cad1c4}caption{text-align:left;font-weight:700;margin-bottom:13px}label{display:block;margin-top:20px}input,select,button{font:inherit;padding:10px;border:1px solid #80917f;border-radius:3px;max-width:100%}input,select{display:block;width:100%;background:white;color:#24392d}button{margin-top:22px;background:#234d42;color:white;cursor:pointer}fieldset{border:1px solid #cad1c4;padding:22px}legend{font-weight:700}button:disabled{opacity:.55;cursor:default}.gallery{list-style:none;padding:0;display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,240px),1fr));gap:24px}figure{margin:0}img{max-width:100%;height:auto}figcaption{font-size:14px}footer{border-top:1px solid #cad1c4;font-size:13px}.tablewrap{overflow:auto}.skip{position:absolute;left:-10000px}.skip:focus{left:20px;top:10px;background:white;padding:10px}[aria-current=page]{font-weight:700;text-decoration-thickness:3px}'''
FORM='''<p class="note" id="demo-notice">Local demonstration. No applications are collected or sent. Use fictional details only.</p><form id="demo-form" action="#demo-notice" method="post"><fieldset id="demo-fields" disabled><legend>Reading-group demonstration</legend><label for="demo-name">Name</label><input id="demo-name" name="name" autocomplete="name" required><label for="demo-email">Email</label><input id="demo-email" name="email" type="email" autocomplete="email" required><label for="demo-session">Session</label><select id="demo-session" name="session" required><option value="">Choose a session</option><option value="morning">Morning</option><option value="afternoon">Afternoon</option></select><button type="submit">Check these example fields</button></fieldset></form><p id="demo-result" role="status"></p><noscript><p>The demonstration fields stay disabled without JavaScript so they cannot send personal details to a nonexistent handler.</p></noscript>'''
JS='''"use strict";const form=document.getElementById("demo-form");if(form){form.addEventListener("submit",event=>{event.preventDefault();document.getElementById("demo-result").textContent="The fields passed the browser checks. No application was sent or saved.";});document.getElementById("demo-fields").disabled=false;}'''

def doc(title,body,nav='',script=False):
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="author" content="{escape(PUBLICATION['author'])}"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} | HTML reference project</title><link rel="stylesheet" href="styles.css">{'<script src="demo.js" defer></script>' if script else ''}</head><body><a class="skip" href="#main">Skip to main content</a><header><p><strong>NEIGHBOURHOOD LIBRARY</strong> / Static reference project</p>{nav}</header><main id="main" tabindex="-1">{body}</main><footer>© {PUBLICATION['copyright_year']} {escape(PUBLICATION['author'])} / CTROTECH reference project. Fictional teaching project. Not a live library service. Inspect the included README before adapting it.</footer></body></html>'''

def build_projects(root,site):
    sets={
    'profile':{'index.html':doc('Volunteer profile','<h1>Ada, library volunteer</h1><p>I help readers find their next book.</p><a href="#contact">Contact information</a><section><h2>At the library</h2><p>Reading-group support, shelf organisation and catalogue help.</p></section><section id="contact"><h2>Contact information</h2><p>In a real service, provide a current contact route here. This fictional profile does not publish personal contact details.</p></section>')},
    'portfolio':{'index.html':doc('Learning portfolio','<h1>A front-end learning portfolio</h1><p>Two static studies in document structure.</p><section><h2>Selected work</h2><article><h3>Library notice board</h3><p>A static notice page with a clear heading structure.</p><a href="project.html">Read the project note</a></article><article><h3>Reading list</h3><p>A semantic list study. No reservation service is connected.</p></article></section>','<nav aria-label="Primary"><a href="index.html" aria-current="page">Portfolio</a><a href="project.html">Project note</a></nav>'), 'project.html':doc('Library notice board project','<h1>Library notice board</h1><p>This fictional portfolio project explores document headings, lists and navigation. It does not claim commercial clients or measured results.</p><section><h2>What it demonstrates</h2><ul><li>Distinct page titles</li><li>Relative document links</li><li>A useful reading order</li></ul></section>','<nav aria-label="Primary"><a href="index.html">Portfolio</a><a href="project.html" aria-current="page">Project note</a></nav>')},
    'registration':{'index.html':doc('Reading-group form','<h1>Reading-group form study</h1>'+FORM,script=True),'demo.js':JS},
    'article':{'index.html':doc('How lending works','<article><h1>How lending works</h1><p>An example policy guide. Replace its content with actual service policy before publication.</p><nav aria-label="On this page"><a href="#borrowing">Borrowing</a><a href="#renewal">Renewal</a><a href="#returns">Returns</a></nav><section id="borrowing"><h2>Borrowing</h2><p>Ask at the desk about the current lending period for the collection.</p></section><section id="renewal"><h2>Renewal</h2><p>Check whether the item can be renewed before its due date.</p></section><section id="returns"><h2>Returns</h2><p>Use the current return instructions for your branch.</p></section><footer><p>Teaching draft dated <time datetime="2026-10-14">14 October 2026</time>.</p></footer></article>')},
    'dashboard':{'index.html':doc('Lending dashboard','<h1>Lending dashboard</h1><p class="note">Fictional static data for an October sample. This page has no live feed.</p><section><h2>Sample loans</h2><div class="tablewrap" tabindex="0" role="region" aria-label="Scrollable sample lending table"><table><caption>Fictional loans by collection</caption><thead><tr><th scope="col">Collection</th><th scope="col">Loans</th><th scope="col">Period</th></tr></thead><tbody><tr><th scope="row">Fiction</th><td>42</td><td>October sample</td></tr><tr><th scope="row">Local history</th><td>18</td><td>October sample</td></tr><tr><th scope="row">Reference</th><td>9</td><td>October sample</td></tr></tbody></table></div></section>')},
    'gallery':{},'capstone':{}}
    gallery='<h1>Library illustration gallery</h1><p>Three local SVG illustrations, not photographs of a real venue.</p><ul class="gallery">'
    art=[('shelves','Three rows of books on a shelf','Organising a small collection.'),('window','A rectangular window divided into six panes','Light in a reading space.'),('tables','Two reading tables seen from above','A study in shared space.')]
    for name,alt,caption in art:
        gallery+=f'<li><figure><img src="{name}.svg" alt="{alt}" width="640" height="400"><figcaption>{caption}</figcaption></figure></li>'
    sets['gallery']['index.html']=doc('Illustration gallery',gallery+'</ul>')
    shapes=''
    for row in range(3):
        for col in range(6):shapes+=f'<rect x="{75+col*82}" y="{55+row*110}" width="54" height="68" rx="2" fill="{["#234d42","#a74125","#8f9e74"][col%3]}"/>'
        shapes+=f'<path d="M55 {130+row*110} H585" stroke="#314739" stroke-width="8"/>'
    sets['gallery']['shelves.svg']=f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 640 400"><rect width="640" height="400" fill="#eee9d9"/>{shapes}</svg>'
    sets['gallery']['window.svg']='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 640 400"><rect width="640" height="400" fill="#eee9d9"/><rect x="140" y="45" width="360" height="310" fill="#c4d8cc" stroke="#234d42" stroke-width="12"/><path d="M260 45 V355 M380 45 V355 M140 200 H500" stroke="#234d42" stroke-width="10"/></svg>'
    sets['gallery']['tables.svg']='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 640 400"><rect width="640" height="400" fill="#eee9d9"/><rect x="90" y="100" width="190" height="200" rx="12" fill="#b78958"/><rect x="360" y="100" width="190" height="200" rx="12" fill="#b78958"/><rect x="130" y="150" width="70" height="90" fill="#234d42"/><rect x="405" y="160" width="70" height="90" fill="#a74125"/></svg>'
    pages={
        'index.html':('Home','<h1>Neighbourhood Library</h1><p>A static reference site for learning HTML.</p><p class="note">No books can be reserved and no applications are collected here.</p><section><h2>Explore the example</h2><ul><li><a href="catalogue.html">Browse fictional book data</a></li><li><a href="membership.html">Inspect a demonstration form</a></li><li><a href="visit.html">Read a visit-information structure</a></li></ul></section>'),
        'catalogue.html':('Catalogue','<h1>Example catalogue</h1><p>Fictional titles for a static HTML exercise.</p><table><caption>Example catalogue entries</caption><thead><tr><th scope="col">Title</th><th scope="col">Collection</th></tr></thead><tbody><tr><th scope="row">Local histories</th><td>Community</td></tr><tr><th scope="row">The walking notebook</th><td>Travel</td></tr><tr><th scope="row">Small gardens</th><td>Practical guides</td></tr></tbody></table>'),
        'membership.html':('Membership','<h1>Membership interface study</h1>'+FORM),
        'visit.html':('Visit','<h1>Plan a visit</h1><p>This is a fictional venue. Do not travel based on these example details.</p><section><h2>Before you leave</h2><p>A real library page should provide verified opening hours, an address and relevant access information.</p></section><section><h2>Access information</h2><p>Describe the actual entrance, step-free route, facilities and a current contact route here. Do not invent accessibility claims for a venue you have not checked.</p></section>')}
    for filename,(title,body) in pages.items():
        nav='<nav aria-label="Primary">'+''.join(f'<a href="{f}" {"aria-current=page" if f==filename else ""}>{t}</a>' for f,(t,_) in pages.items())+'</nav>'
        sets['capstone'][filename]=doc(title,body,nav,filename=='membership.html')
    sets['capstone']['demo.js']=JS
    for slug,files in sets.items():
        folder=site/'projects'/slug;folder.mkdir(parents=True,exist_ok=True)
        files['styles.css']=CSS
        files['README.md']=f'''# {slug.capitalize()} reference project\n\nA static HTML teaching implementation for the CTROTECH HTML Playbook review edition.\n\nUse a local HTTP server or open index.html for the static documents. All included styles and image assets are local. Demo forms never submit when their script is active; fields remain disabled without script. They are not connected to a real service. Use fictional values only.\n\n## Review tasks\n- Check complete documents with a recorded Nu checker version.\n- Follow every internal navigation and fragment link.\n- Use the keyboard to reach available controls and keep focus visible.\n- Inspect labels, headings, table relationships and image alternatives as relevant.\n- Inspect the layout at narrow widths and with longer content.\n- Distinguish this static example from a deployed backend.\n\nChapter briefs and explained exercises are in the book. The capstone rubric awards up to four points for each of seven areas: structure, semantic choice, keyboard/focus behavior, labels/errors, content clarity, resource reliability and maintainability. Record observations, not a certification claim.\n'''
        for name,content in files.items():(folder/name).write_text(content)
        with zipfile.ZipFile(site/'downloads'/f'project-{slug}.zip','w',zipfile.ZIP_DEFLATED) as z:
            for p in folder.iterdir():z.write(p,slug+'/'+p.name)
